import json, numpy as np
d=json.load(open('train.json'))
persons=list(d.keys())

def build_curve(pids, field, how='mean'):
    bymin={}
    for pid in pids:
        for r in d[pid]:
            v=r[field]
            if v is not None: bymin.setdefault(r['time_min'],[]).append(v)
    f=np.median if how=='med' else np.mean
    return {m:f(v) for m,v in bymin.items()}

def cv(c,m):
    ks=sorted(c)
    if m<=ks[0]: return c[ks[0]]
    if m>=ks[-1]: return c[ks[-1]]
    lo=max(k for k in ks if k<=m); hi=min(k for k in ks if k>=m)
    if lo==hi: return c[lo]
    w=(m-lo)/(hi-lo); return c[lo]*(1-w)+c[hi]*w

def origins(pid):
    rows=d[pid]; ws=[r['watts'] for r in rows]
    fd=None
    for i in range(1,len(ws)):
        if ws[i] is not None and ws[i-1] is not None and ws[i]<ws[i-1]: fd=i;break
    if fd is None: return []
    return [i for i in range(fd,len(rows)-15) if rows[i+15]['core_temp'] is not None]

# row-level core ~ hr,skin,elapsed mapping
def rowfit(pids):
    X=[];y=[]
    for p in pids:
        for r in d[p]:
            if r['core_temp'] is None or r['hr'] is None or r['skin_temp'] is None: continue
            X.append([r['hr'], r['skin_temp'], r['time_min'],1.0]); y.append(r['core_temp'])
    X=np.array(X);y=np.array(y)
    w,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    return w

res={}
for name in ['curve_med','curve_mean','hrmap+delta','mix']:
    res[name]=[]
resid_all={'curve_med':[], 'mix':[]}
for hold in persons:
    oi=origins(hold)
    if not oi: continue
    tr=[p for p in persons if p!=hold]
    ccm=build_curve(tr,'core_temp','med'); cca=build_curve(tr,'core_temp','mean')
    w=rowfit(tr)
    rows=d[hold]
    for i in oi:
        m=rows[i]['time_min']; tgt=rows[i+15]['core_temp']
        p1=cv(ccm,m+15); p2=cv(cca,m+15)
        hr=rows[i]['hr'] if rows[i]['hr'] is not None else None
        sk=rows[i]['skin_temp']
        if hr is not None and sk is not None:
            cur=np.dot(w,[hr,sk,m,1.0])
        else:
            cur=cv(ccm,m)
        p3=cur+(cv(ccm,m+15)-cv(ccm,m))
        p4=0.5*p1+0.5*p3
        res['curve_med'].append((hold,abs(p1-tgt))); resid_all['curve_med'].append(p1-tgt)
        res['curve_mean'].append((hold,abs(p2-tgt)))
        res['hrmap+delta'].append((hold,abs(p3-tgt)))
        res['mix'].append((hold,abs(p4-tgt))); resid_all['mix'].append(p4-tgt)
for name,v in res.items():
    bp={}
    for p,e in v: bp.setdefault(p,[]).append(e)
    pb=np.mean([np.mean(es) for es in bp.values()])
    print(name, 'pb-mae', round(pb,4), 'mae', round(np.mean([e for _,e in v]),4))
r=np.array(resid_all['curve_med'])
print('curve_med resid pct', np.percentile(r,[5,25,50,75,95]).round(3))
r=np.array(resid_all['mix'])
print('mix resid pct', np.percentile(r,[5,25,50,75,95]).round(3))
EOF"]}

