import json, numpy as np
d=json.load(open('train.json'))
persons=list(d.keys())

def build_curve(pids):
    bymin={}
    for pid in pids:
        for r in d[pid]:
            if r['core_temp'] is not None: bymin.setdefault(r['time_min'],[]).append(r['core_temp'])
    return {m:np.median(v) for m,v in bymin.items()}

def smooth(c):
    ks=sorted(c); vs=np.array([c[k] for k in ks])
    # moving average window 5, then enforce monotone-ish via isotonic-lite (no, keep MA)
    out={}
    for i,k in enumerate(ks):
        lo=max(0,i-2); hi=min(len(ks),i+3)
        out[k]=vs[lo:hi].mean()
    return out

def cvv(c,m):
    ks=sorted(c)
    if m<=ks[0]: return c[ks[0]]
    if m>=ks[-1]: return c[ks[-1]]
    lo=max(k for k in ks if k<=m); hi=min(k for k in ks if k>=m)
    if lo==hi: return c[lo]
    w=(m-lo)/(hi-lo); return c[lo]*(1-w)+c[hi]*w

def origins(pid):
    rows=d[pid]; ws=[r['watts'] for r in rows]
    fd=None
    for i in range(1,len(ws)):
        if ws[i] is not None and ws[i-1] is not None and ws[i]<ws[i-1]: fd=i;break
    if fd is None: return []
    return [i for i in range(fd,len(rows)-15) if rows[i+15]['core_temp'] is not None]

def personoff_fit(pids, feat):
    xs=[];ys=[]
    c=build_curve(pids)
    for p in pids:
        rows=d[p]
        offs=[r['core_temp']-cvv(c,r['time_min']) for r in rows if r['core_temp'] is not None and 30<=r['time_min']<=55]
        xs.append(feat(rows)); ys.append(np.mean(offs))
    xs=np.array(xs);ys=np.array(ys)
    b=np.polyfit(xs,ys,1)
    return b

massf=lambda rows: rows[0]['mass'] or 74.0
bsaf=lambda rows: 0.007184*(rows[0]['mass'] or 74)**0.425*(rows[0]['height'] or 172)**0.725

variants={'med':{}, 'med_smooth':{}, 'med+mass':{}, 'med_smooth+mass':{}, 'med+bsa':{}}
for hold in persons:
    oi=origins(hold)
    if not oi: continue
    tr=[p for p in persons if p!=hold]
    c=build_curve(tr); cs=smooth(c)
    bm=personoff_fit(tr,massf); bb=personoff_fit(tr,bsaf)
    rows=d[hold]
    for i in oi:
        m=rows[i]['time_min']; tgt=rows[i+15]['core_temp']
        p1=cvv(c,m+15); p2=cvv(cs,m+15)
        adjm=np.polyval(bm,massf(rows)); adjb=np.polyval(bb,bsaf(rows))
        for name,pred in [('med',p1),('med_smooth',p2),('med+mass',p1+adjm),('med_smooth+mass',p2+adjm),('med+bsa',p1+adjb)]:
            variants[name].setdefault(hold,[]).append(abs(pred-tgt))
for name,bp in variants.items():
    pb=np.mean([np.mean(v) for v in bp.values()])
    print(name, round(pb,4), {k:round(np.mean(v),2) for k,v in bp.items()})
EOF"]}

